# Localized names supplied by the installed-game catalog generator.
from catalog_languages import CATALOG_LABELS
for _source,_labels in CATALOG_LABELS.items():
    # The legacy catalog text is Polish even when a part name is already English.
    ENGLISH.setdefault(_source,_labels['en'])
    for _code in ('de','fr','es','pt'):
        TRANSLATIONS[_code].setdefault(ENGLISH[_source],_labels[_code])
